export type SkillCategory =
  | 'Active'
  | 'Passive'
  | 'Summon'
  | 'Aura'
  | 'Melee'
  | 'Relic'
  | 'Ritual'
  | 'Curse'
  | 'Orbit';

export type SkillElement =
  | 'fire'
  | 'frost'
  | 'blood'
  | 'void'
  | 'earth'
  | 'lightning'
  | 'physical'
  | 'necrotic'
  | 'dark'
  | 'shadow';

export type SkillRarity = 'Common' | 'Uncommon' | 'Rare' | 'Epic' | 'Legendary' | 'Mythic';

export interface BossSkillDef {
  id: string;
  bossId: string;
  name: string;
  icon: string;
  element: SkillElement;
  category: SkillCategory;
  rarity: SkillRarity;
  desc: string;
  maxLevel: number;
  baseCooldown: number;
  baseDamage: number;
  statBonus: string;
  color: string;
  tags: string[];
  resourceCost?: number;
  essenceCost?: number;
  furyCost?: number;
  bloodCost?: number;
  effectType:
    | 'melee_cleave'
    | 'projectile'
    | 'summon'
    | 'orbit'
    | 'aura'
    | 'decal'
    | 'passive_stat'
    | 'chain'
    | 'nova'
    | 'strike'
    | 'ritual'
    | 'curse';
  summonType?:
    | 'skeleton'
    | 'bat'
    | 'shadow_clone'
    | 'golem_minion'
    | 'fire_wisp'
    | 'ash_clone'
    | 'bone_sentinel'
    | 'crypt_archer'
    | 'grave_spearman'
    | 'grave_hound'
    | 'bone_mage'
    | 'ossuary_guardian'
    | 'wight_captain'
    | 'corpse_collector'
    | 'dread_abomination'
    | 'skeletal_dragon'
    | 'vampire_bat'
    | 'crimson_familiar'
    | 'nightwing_sentinel'
    | 'blood_seraph';
  maxSummons?: number;
  projectileCount?: number;
  pierce?: number;
  splashRadius?: number;
  orbitCount?: number;
  lifeSteal?: number;
  critChanceBonus?: number;
  critDamageBonus?: number;
  areaBonus?: number;
  speedBonus?: number;
  hpBonus?: number;
  armorBonus?: number;
  burnDps?: number;
  freezeDuration?: number;
  stunDuration?: number;
  duration?: number;
}

export type TreeBranchType =
  // Demon Monarch Branches
  | 'SWORDSMANSHIP'
  | 'HELLFIRE'
  | 'DEMONIC_POWERS'
  | 'PHYSICAL_ATTACKS'
  | 'INFERNAL_ASCENSION'
  // Lich Lord Branches
  | 'SUMMONING'
  | 'FROST'
  | 'SORCERY'
  | 'DARK'
  | 'RITUAL'
  // Vampire Queen Branches
  | 'BLOOD_SORCERY'
  | 'VAMPIRIC_HUNTING'
  | 'BAT_CREATURES'
  | 'MIST_DOMINATION'
  | 'ROYAL_BLOOD_RITUALS'
  // Shadow Reaper Branches
  | 'SCYTHE_MASTERY'
  | 'SHADOW_MOVEMENT'
  | 'HAUNTING_CLONES'
  | 'SOUL_HARVESTING'
  | 'FORBIDDEN_REAPER_ARTS'
  // Cursed Golem Branches
  | 'COLOSSAL_PHYSICAL_COMBAT'
  | 'EARTH_STONE_MAGIC'
  | 'ANCIENT_RUNIC_MAGIC'
  | 'FORTRESS_DEFENSE'
  | 'GRAVITY_CATACLYSM'
  // Passives
  | 'PASSIVES';

export interface CharacterSkillTreeNode {
  id: string;
  bossId: string;
  name: string;
  branch: TreeBranchType;
  icon: string;
  element: SkillElement;
  type: 'active' | 'passive';
  maxRank: number;
  resourceCost: number; // Fury, Essence, or Blood Essence
  cooldown: number;
  damage: number;
  desc: string;
  rankBonus: string;
  evolutions?: {
    rank5?: string;
    rank10?: string;
    rank15?: string;
    rank20?: string;
  };
  summonType?: BossSkillDef['summonType'];
  effectType: BossSkillDef['effectType'];
  color: string;
  furyGain?: number;
  bloodGain?: number;
  lifeSteal?: number;
  burnDps?: number;
  slashRadius?: number;
  projectileCount?: number;
  pierce?: number;
  orbitCount?: number;
  areaBonus?: number;
  speedBonus?: number;
  hpBonus?: number;
  armorBonus?: number;
  freezeDuration?: number;
  stunDuration?: number;
  duration?: number;
}

export interface CharacterMasteryState {
  exp: number;
  rank: number;
}

export interface CharacterProgressionData {
  skillPoints: number;
  allocatedSkills: Record<string, number>;
  abilityMastery: Record<string, CharacterMasteryState>;
  loadout: [string, string, string, string, string];
  unlockedUltimates: string[];
}

export interface CharacterMilestoneUltimate {
  levelReq: number;
  id: string;
  name: string;
  desc: string;
  cooldown: number;
  resourceCost: number;
  icon: string;
  color: string;
}

