// Aliases for backwards compatibility
export type LichProgressionData = CharacterProgressionData;
export type LichSkillTreeNode = CharacterSkillTreeNode;
export type LichTreeBranch = TreeBranchType;

// Helper to calculate total available skill points for ANY character
export function calculateCharacterSkillPoints(level: number): number {
  if (level <= 1) return 0;
  const basePoints = (level - 1) * 2;
  const bonusMilestonePoints = Math.floor(level / 10);
  return basePoints + bonusMilestonePoints;
}

export const calculateLichLordSkillPoints = calculateCharacterSkillPoints;

// Helper to get character-specific branches
export function getCharacterBranches(bossId: string): Array<{ id: TreeBranchType; label: string; icon: string }> {
  if (bossId === 'demon_monarch') {
    return [
      { id: 'SWORDSMANSHIP', label: 'A. Infernal Greatsword Arts (10)', icon: 'Swords' },
      { id: 'HELLFIRE', label: 'B. Volcanic Eruptions & Slams (10)', icon: 'Flame' },
      { id: 'DEMONIC_POWERS', label: 'C. Demonic Sword Mobility & Counters (10)', icon: 'Zap' },
      { id: 'PHYSICAL_ATTACKS', label: 'D. Physical Demonic Fury Arts (10)', icon: 'Shield' },
      { id: 'INFERNAL_ASCENSION', label: 'E. Infernal Sword Ascension (10)', icon: 'Trophy' },
      { id: 'PASSIVES', label: 'Greatsword Passives (20)', icon: 'Star' },
    ];
  }
  if (bossId === 'vampire_queen') {
    return [
      { id: 'BLOOD_SORCERY', label: 'A. Blood Sorcery (10)', icon: 'Flame' },
      { id: 'VAMPIRIC_HUNTING', label: 'B. Vampiric Hunting (10)', icon: 'Swords' },
      { id: 'BAT_CREATURES', label: 'C. Bats & Night Creatures (10)', icon: 'Activity' },
      { id: 'MIST_DOMINATION', label: 'D. Mist & Domination (10)', icon: 'Shield' },
      { id: 'ROYAL_BLOOD_RITUALS', label: 'E. Royal Blood Rituals (10)', icon: 'Trophy' },
      { id: 'PASSIVES', label: 'Passives (20)', icon: 'Star' },
    ];
  }
  if (bossId === 'shadow_reaper') {
    return [
      { id: 'SCYTHE_MASTERY', label: 'A. Scythe Mastery (10)', icon: 'Swords' },
      { id: 'SHADOW_MOVEMENT', label: 'B. Shadow Movement (10)', icon: 'Activity' },
      { id: 'HAUNTING_CLONES', label: 'C. Haunting & Clones (10)', icon: 'Skull' },
      { id: 'SOUL_HARVESTING', label: 'D. Soul Harvesting (10)', icon: 'Crosshair' },
      { id: 'FORBIDDEN_REAPER_ARTS', label: 'E. Forbidden Reaper Arts (10)', icon: 'Trophy' },
      { id: 'PASSIVES', label: 'Passives (20)', icon: 'Star' },
    ];
  }
  if (bossId === 'cursed_golem') {
    return [
      { id: 'COLOSSAL_PHYSICAL_COMBAT', label: 'A. Colossal Combat (10)', icon: 'Shield' },
      { id: 'EARTH_STONE_MAGIC', label: 'B. Earth & Stone Magic (10)', icon: 'Target' },
      { id: 'ANCIENT_RUNIC_MAGIC', label: 'C. Ancient Runic Magic (10)', icon: 'Sparkles' },
      { id: 'FORTRESS_DEFENSE', label: 'D. Fortress & Defense (10)', icon: 'Shield' },
      { id: 'GRAVITY_CATACLYSM', label: 'E. Gravity & Cataclysm (10)', icon: 'Trophy' },
      { id: 'PASSIVES', label: 'Passives (20)', icon: 'Star' },
    ];
  }
  // Default Lich Lord / others
  return [
    { id: 'SUMMONING', label: 'A. Undead Summoning (10)', icon: 'Skull' },
    { id: 'FROST', label: 'B. Frost & Death (10)', icon: 'Snowflake' },
    { id: 'SORCERY', label: 'C. Sorcery (10)', icon: 'Flame' },
    { id: 'DARK', label: 'D. Dark Magic (10)', icon: 'Sparkles' },
    { id: 'RITUAL', label: 'E. Rituals (10)', icon: 'Shield' },
    { id: 'PASSIVES', label: 'Passives (20)', icon: 'Star' },
  ];
}

