// Master Registry indexing all skills
export const ALL_BOSS_SKILLS: Record<string, BossSkillDef> = {};

[
  ...DEMON_DRAFT_SKILLS,
  ...LICH_DRAFT_SKILLS,
  ...VAMPIRE_DRAFT_SKILLS,
  ...REAPER_DRAFT_SKILLS,
  ...GOLEM_DRAFT_SKILLS,
  ...UNIVERSAL_RELICS,
].forEach((skill) => {
  ALL_BOSS_SKILLS[skill.id] = skill;
});

// Helper to get all 50 skills for a specific boss
export function getBossSkills(bossId: string): BossSkillDef[] {
  return Object.values(ALL_BOSS_SKILLS).filter((s) => s.bossId === bossId);
}

// Weighted Draft Pool Generator for active character
export function generateCharacterDraftPool(
  bossId: string,
  activeSkills: Map<string, { level: number; timer: number }>,
  poolCount = 3
): string[] {
  const bossPool = Object.values(ALL_BOSS_SKILLS).filter(
    (s) => s.bossId === bossId || s.bossId === 'universal'
  );

  const available = bossPool.filter((sk) => {
    const cur = activeSkills.get(sk.id);
    return !cur || cur.level < sk.maxLevel;
  });

  if (available.length === 0) return [];

  // Rarity weighting
  const weights: Record<SkillRarity, number> = {
    Common: 50,
    Uncommon: 30,
    Rare: 15,
    Epic: 6,
    Legendary: 2,
    Mythic: 0.8,
  };

  const selected: string[] = [];
  const candidatePool = [...available];

  while (selected.length < poolCount && candidatePool.length > 0) {
    const totalWeight = candidatePool.reduce((sum, item) => sum + (weights[item.rarity] || 10), 0);
    let randomVal = Math.random() * totalWeight;

    let pickedIdx = 0;
    for (let i = 0; i < candidatePool.length; i++) {
      const w = weights[candidatePool[i].rarity] || 10;
      if (randomVal <= w) {
        pickedIdx = i;
        break;
      }
      randomVal -= w;
    }

    selected.push(candidatePool[pickedIdx].id);
    candidatePool.splice(pickedIdx, 1);
  }

  return selected;
}
